namespace Challenge;public record UploadResult(bool Accepted,string? Path,string? Error);public static class Uploads{public static UploadResult Save(string root,string fileName,string contentType,Stream input,int maxBytes){Directory.CreateDirectory(root);using var data=new MemoryStream();var buffer=new byte[8192];int total=0,n;while((n=input.Read(buffer,0,Math.Min(buffer.Length,maxBytes+1-total)))>0){total+=n;if(total>maxBytes)return new(false,null,"too_large");data.Write(buffer,0,n);}var b=data.ToArray();var ext=b.Length>=5&&b.AsSpan(0,5).SequenceEqual("%PDF-"u8)?".pdf":b.Length>=8&&b.AsSpan(0,8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10})?".png":null;if(ext is null)return new(false,null,"invalid_type");var path=System.IO.Path.Combine(System.IO.Path.GetFullPath(root),Guid.NewGuid().ToString("N")+ext);File.WriteAllBytes(path,b);return new(true,path,null);}}
